import{_ as o,l,o as e,c as P,v as t,p as s,x as r,d as p,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"MPTCP","description":"","frontmatter":{"title":"MPTCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mptcp.md","filePath":"cs/mptcp.md","lastUpdated":1789023840000}'),d={name:"cs/mptcp.md"};function C(T,a,h,A,_,m){const i=l("Mermaid");return e(),P("div",null,[a[1]||(a[1]=t('<h1 id="mptcp" tabindex="-1">MPTCP <a class="header-anchor" href="#mptcp" aria-label="Permalink to &quot;MPTCP&quot;">​</a></h1><div class="epigraph"><p>一条逻辑 TCP 绑多条子流，各走不同地址或路径；应用仍看见一条字节流，调度在子流间搬数据。</p><footer>—— 据 RFC 8684 MPTCP；Raiciu et al., SIGCOMM 2011 整理</footer></div><p><a href="/cs/tso-lro">TSO</a> 结束单路径细节。主干仍是单四元组。<a href="/cs/tso-lro">上一课</a> 不解决 Wi‑Fi+蜂窝同时用。缺口是 <strong>MPTCP</strong>：子流、令牌、耦合拥塞。本课不把 SCTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手机有 WLAN 与 LTE 两地址，单 TCP 只能钉一条。MPTCP：主子流握手后再 ADD_ADDR 开子流，DSS 映射到数据级序号。拥塞：若各子流独立 AIMD，会在共享瓶颈偷两份——要耦合（如 LIA）。中间盒若剥 MPTCP 选项则回退普通 TCP。与 LACP/ECMP：那些是跳内哈希；MPTCP 是端到端多路径。</p><p>不要把 MPTCP 写成 QUIC 迁移的拷贝，下一课对照。</p><p><span class="marginnote">RFC 8684。部署受 NAT 与 API 限制。本课不把每种调度器（minRTT 等）写完。</span></p><h3 id="一条逻辑字节流" tabindex="-1">一条逻辑字节流 <a class="header-anchor" href="#一条逻辑字节流" aria-label="Permalink to &quot;一条逻辑字节流&quot;">​</a></h3><p>子流可走 Wi‑Fi 与蜂窝。拥塞要耦合，防共享瓶颈加倍。中间剥选项则回退 TCP。ADD_ADDR 要令牌。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：应用套接字 → 逻辑连接 → 子流 A/B。对照 SCTP 多宿：SCTP 是另一协议，MPTCP 兼容 TCP 应用。</p>',11)),(e(),s(c,null,{default:r(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E4%B8%80%E6%9D%A1%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%20--%3E%20MP%5B%22MPTCP%20%E6%98%A0%E5%B0%84%22%5D%0A%20%20MP%20--%3E%20S1%5B%22%E5%AD%90%E6%B5%81%20Wi-Fi%22%5D%0A%20%20MP%20--%3E%20S2%5B%22%E5%AD%90%E6%B5%81%20%E8%9C%82%E7%AA%9D%22%5D%0A%20%20CC%5B%22%E8%80%A6%E5%90%88%E6%8B%A5%E5%A1%9E%22%5D%20--%3E%20S1%0A%20%20CC%20--%3E%20S2%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BDP 是各子流之和，窗口缩放每子流协商。RPKI 与路径无关。半开保活要每子流或逻辑层。数据中心 ECMP 已多路径，MPTCP 再开可能过度。无线 TCP 后课的误码在子流间可避开坏口。</p><p>安全：ADD_ADDR 要令牌，防劫持子流。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MP-QUIC 的全部。SCTP 对照是下一课。后课默认：MPTCP 把多径对应用隐藏为一条 TCP。</p><p>内核/库未开则应用无感也无益。</p><p>上一课留下的缺口在本课收口；「MPTCP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/sctp">SCTP 对照</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多子流一条逻辑字节流。</li><li>拥塞要耦合，防共享瓶颈加倍。</li><li>中间盒可能迫使回退。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8684；Raiciu et al., 2011。</li></ul>',10))])}const u=o(d,[["render",C]]);export{E as __pageData,u as default};
